GetActivity:
query GetActivity($feedType: ActivityFeed, $first: Int, $after: String, $last: Int, $before: String) {
  activity(
    feedType: $feedType
    first: $first
    after: $after
    last: $last
    before: $before
  ) {
    nodes {
      id
      eventCategory
      createdAt
      completionStatusChange {
        before
        after
      }
      user {
        id
        username
        slug
        avatarUrl(size: SMALL)
      }
      eventable {
        ... on GamePurchase {
          game {
            id
            name
            coverUrl(size: SMALL)
          }
          completionStatus
          rating
        }
        ... on FavoriteGame {
          game {
            id
            name
            coverUrl(size: SMALL)
          }
        }
        ... on Relationship {
          followed {
            id
            username
            slug
            avatarUrl(size: SMALL)
          }
        }
        ... on User {
          id
          username
          slug
          avatarUrl(size: SMALL)
        }
      }
    }
    pageInfo {
      hasNextPage
      startCursor
      endCursor
    }
  }
}

