GetComparisonInCommon:
query GetComparisonInCommon($userASlug: String!, $userBSlug: String!, $first: Int!, $after: String, $sortBy: LibraryComparisonSort, $search: String, $bothRated: Boolean) {
  libraryComparison(userASlug: $userASlug, userBSlug: $userBSlug) {
    inCommon(
      first: $first
      after: $after
      sortBy: $sortBy
      search: $search
      bothRated: $bothRated
    ) {
      totalCount
      pageInfo {
        hasNextPage
        endCursor
      }
      nodes {
        game {
          id
          name
          coverUrl(size: SMALL)
          developers(first: 1) {
            nodes {
              id
              name
            }
          }
        }
        purchaseA {
          id
          rating
          completionStatus
        }
        purchaseB {
          id
          rating
          completionStatus
        }
        ratingDifference
      }
    }
  }
}

GetComparisonOnly:
query GetComparisonOnly($userASlug: String!, $userBSlug: String!, $sideA: Boolean!, $first: Int!, $after: String, $sortBy: GamePurchaseSort, $search: String) {
  libraryComparison(userASlug: $userASlug, userBSlug: $userBSlug) {
    onlyA(first: $first, after: $after, sortBy: $sortBy, search: $search) @include(if: $sideA) {
      ...ComparisonOnlyFields
    }
    onlyB(first: $first, after: $after, sortBy: $sortBy, search: $search) @skip(if: $sideA) {
      ...ComparisonOnlyFields
    }
  }
}

