GetLibraryShelves:
query GetLibraryShelves($slug: String!, $first: Int!, $search: String, $sortBy: GamePurchaseSort, $platformIds: [ID!], $storeIds: [ID!], $minRating: Int, $maxRating: Int) {
  user(slug: $slug) {
    id
    inProgress: gamePurchases(
      first: $first
      completionStatus: IN_PROGRESS
      search: $search
      sortBy: $sortBy
      platformIds: $platformIds
      storeIds: $storeIds
      minRating: $minRating
      maxRating: $maxRating
    ) {
      totalCount
      nodes {
        ...LibraryPlayingPurchaseFields
      }
    }
    paused: gamePurchases(
      first: $first
      completionStatus: PAUSED
      search: $search
      sortBy: $sortBy
      platformIds: $platformIds
      storeIds: $storeIds
      minRating: $minRating
      maxRating: $maxRating
    ) {
      ...LibraryShelfFields
    }
    completed: gamePurchases(
      first: $first
      completionStatus: COMPLETED
      search: $search
      sortBy: $sortBy
      platformIds: $platformIds
      storeIds: $storeIds
      minRating: $minRating
      maxRating: $maxRating
    ) {
      ...LibraryShelfFields
    }
    fullyCompleted: gamePurchases(
      first: $first
      completionStatus: FULLY_COMPLETED
      search: $search
      sortBy: $sortBy
      platformIds: $platformIds
      storeIds: $storeIds
      minRating: $minRating
      maxRating: $maxRating
    ) {
      ...LibraryShelfFields
    }
    unplayed: gamePurchases(
      first: $first
      completionStatus: UNPLAYED
      search: $search
      sortBy: $sortBy
      platformIds: $platformIds
      storeIds: $storeIds
      minRating: $minRating
      maxRating: $maxRating
    ) {
      ...LibraryShelfFields
    }
    dropped: gamePurchases(
      first: $first
      completionStatus: DROPPED
      search: $search
      sortBy: $sortBy
      platformIds: $platformIds
      storeIds: $storeIds
      minRating: $minRating
      maxRating: $maxRating
    ) {
      ...LibraryShelfFields
    }
    notApplicable: gamePurchases(
      first: $first
      completionStatus: NOT_APPLICABLE
      search: $search
      sortBy: $sortBy
      platformIds: $platformIds
      storeIds: $storeIds
      minRating: $minRating
      maxRating: $maxRating
    ) {
      ...LibraryShelfFields
    }
    noStatus: gamePurchases(
      first: $first
      noCompletionStatus: true
      search: $search
      sortBy: $sortBy
      platformIds: $platformIds
      storeIds: $storeIds
      minRating: $minRating
      maxRating: $maxRating
    ) {
      ...LibraryShelfFields
    }
  }
}

