  groupedUnmatchedGames(first: $first, after: $after) {
    nodes {
      externalServiceName
      externalServiceId
      name
      count
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

GetUserActivity:
query GetUserActivity($slug: String!, $first: Int, $after: String, $last: Int, $before: String) {
  user(slug: $slug) {
    id
    username
    slug
    activity(first: $first, after: $after, last: $last, before: $before) {
      nodes {
        id
        eventCategory
        createdAt
        completionStatusChange {
          before
          after
        }
        user {
          id
          username
          slug
          avatarUrl(size: SMALL)
        }
        eventable {
          ... on GamePurchase {
            game {
              id
              name
              coverUrl(size: SMALL)
            }
            completionStatus
            rating
          }
          ... on FavoriteGame {
            game {
              id
              name
              coverUrl(size: SMALL)
            }
          }
          ... on Relationship {
            followed {
              id
              username
              slug
              avatarUrl(size: SMALL)
            }
          }
          ... on User {
            id
            username
            slug
            avatarUrl(size: SMALL)
          }
        }
      }
      pageInfo {
        hasNextPage
        startCursor
        endCursor
      }
    }
  }
}

