GetUserOverview:
query GetUserOverview($slug: String!, $favoritesCount: Int!, $playingCount: Int!, $topRatedCount: Int!) {
  user(slug: $slug) {
    id
    bio
    favoritedGames(first: $favoritesCount) {
      totalCount
      nodes {
        id
        name
        coverUrl(size: SMALL)
      }
    }
    playing: gamePurchases(
      first: $playingCount
      completionStatus: IN_PROGRESS
      sortBy: MOST_HOURS_PLAYED
    ) {
      totalCount
      nodes {
        ...LibraryPlayingPurchaseFields
      }
    }
    topRated: gamePurchases(first: $topRatedCount, sortBy: HIGHEST_RATING) {
      totalCount
      nodes {
        ...LibraryGamePurchaseFields
      }
    }
  }
}

fragment LibraryGamePurchaseFields on GamePurchase {
  id
  game {
    id
    name
    coverUrl(size: SMALL)
  }
  hoursPlayed
  completionStatus
  rating
}

fragment LibraryPlayingPurchaseFields on GamePurchase {
  ...LibraryGamePurchaseFields
  startDate
  platforms(first: 3) {
    nodes {
      id
      name
    }
  }
  stores(first: 3) {
    nodes {
      id
      name
    }
  }
}

